import * as THREE from 'three';
// Intersection contours preserve holes already modeled in the surface. Open contours are omitted.
export function sectionGeometry(mesh,plane){mesh.updateWorldMatrix(true,false);const local=plane.clone().applyMatrix4(mesh.matrixWorld.clone().invert()),geo=mesh.geometry,pos=geo.attributes.position,idx=geo.index;geo.computeBoundingBox();if(!local.intersectsBox(geo.boundingBox))return null;
 const axis=Math.abs(plane.normal.y)<.9?new THREE.Vector3(0,1,0):new THREE.Vector3(1,0,0),u=axis.cross(plane.normal).normalize(),v=plane.normal.clone().cross(u).normalize(),origin=plane.coplanarPoint(new THREE.Vector3()),points=[],adj=new Map(),keys=new Map(),edges=new Set();
 const get=p=>{const world=p.clone().applyMatrix4(mesh.matrixWorld),q=new THREE.Vector2(world.dot(u),world.dot(v)),key=Math.round(q.x*1e5)+','+Math.round(q.y*1e5);if(keys.has(key))return keys.get(key);const i=points.length;keys.set(key,i);points.push(q);adj.set(i,new Set());return i;};
 const verts=[new THREE.Vector3(),new THREE.Vector3(),new THREE.Vector3()],count=idx?idx.count:pos.count;
 for(let i=0;i<count;i+=3){const ds=verts.map((p,k)=>local.distanceToPoint(p.fromBufferAttribute(pos,idx?idx.getX(i+k):i+k)));if(ds.every(d=>d>=0)||ds.every(d=>d<=0))continue;const hits=[];for(let k=0;k<3;k++){const j=(k+1)%3;if((ds[k]<0)!==(ds[j]<0)){hits.push(verts[k].clone().lerp(verts[j],ds[k]/(ds[k]-ds[j])));}}if(hits.length!==2)continue;const a=get(hits[0]),b=get(hits[1]);if(a===b)continue;const key=a<b?a+':'+b:b+':'+a;if(edges.has(key))continue;edges.add(key);adj.get(a).add(b);adj.get(b).add(a);}
 const visited=new Set(),loops=[];for(const start of adj.keys()){if(visited.has(start))continue;let prev=-1,cur=start,loop=[],closed=false;while(!visited.has(cur)){visited.add(cur);loop.push(points[cur]);const ns=[...adj.get(cur)];if(ns.length!==2)break;const next=ns.find(n=>n!==prev);prev=cur;cur=next;if(cur===start){closed=true;break;}}if(closed&&loop.length>=3&&Math.abs(THREE.ShapeUtils.area(loop))>1e-10)loops.push(loop);}
 if(!loops.length)return null;
 const contains=(poly,p)=>{let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a.y>p.y)!==(b.y>p.y)&&p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)inside=!inside;}return inside;};
 const nodes=loops.map(p=>({p,area:Math.abs(THREE.ShapeUtils.area(p)),parent:null,depth:0})).sort((a,b)=>b.area-a.area);for(let i=0;i<nodes.length;i++){const n=nodes[i];for(let j=i-1;j>=0;j--)if(contains(nodes[j].p,n.p[0])){n.parent=nodes[j];n.depth=nodes[j].depth+1;break;}}
 const positions=[],outline=[];for(const n of nodes){for(let i=0;i<n.p.length;i++){for(const q of [n.p[i],n.p[(i+1)%n.p.length]]){const w=origin.clone().addScaledVector(u,q.x).addScaledVector(v,q.y);outline.push(...w);}}if(n.depth%2)continue;const holes=nodes.filter(h=>h.parent===n).map(h=>h.p),all=[...n.p,...holes.flat()];for(const face of THREE.ShapeUtils.triangulateShape(n.p,holes))for(const id of face){const q=all[id],w=origin.clone().addScaledVector(u,q.x).addScaledVector(v,q.y);positions.push(...w);}}
 if(!positions.length)return null;const result=new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(positions,3));result.computeVertexNormals();return {geometry:result,outline:new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(outline,3)),loops:loops.length};}
export function sectionMaterial(kind,color){const m=new THREE.MeshStandardMaterial({color,side:THREE.DoubleSide,roughness:.72,polygonOffset:true,polygonOffsetFactor:-2,polygonOffsetUnits:-2});const tissue=kind==='bone'?1:kind==='lung'?2:['muscle','heart','tendon','nerve'].includes(kind)?3:0;m.onBeforeCompile=s=>{s.vertexShader='varying vec3 cutP;\n'+s.vertexShader;s.vertexShader=s.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\ncutP=position;');s.fragmentShader=`varying vec3 cutP;float cutHash(vec3 p){return fract(sin(dot(p,vec3(127.1,311.7,74.7)))*43758.5453);}\n`+s.fragmentShader;s.fragmentShader=s.fragmentShader.replace('#include <color_fragment>',`#include <color_fragment>
 vec3 cells=cutP*${tissue===1?'1600.':'2100.'};float n=cutHash(floor(cells));float pores=smoothstep(.19,.32,length(fract(cells)-.5));float fiber=.5+.5*sin(cutP.y*6500.+sin(cutP.x*1200.)*2.);diffuseColor.rgb*=${tissue===1?'mix(.43,1.1,pores)*(.9+.2*n)':tissue===2?'mix(.45,1.08,pores)*(.9+.18*n)':tissue===3?'(.76+.2*fiber+.13*n)':'(.82+.3*n)'};`);};m.customProgramCacheKey=()=>`section-${tissue}`;return m;}
export class SectionCaps{
 constructor(scene,render){this.group=new THREE.Group();scene.add(this.group);this.render=render;this.ticket=0;}
 clear(){this.ticket++;for(const o of [...this.group.children]){o.geometry.dispose();o.material.dispose();this.group.remove(o);}}
 async update(objects,planes){this.clear();const ticket=this.ticket;if(!planes.length)return;let i=0;for(const o of objects.values()){if(ticket!==this.ticket)return;if(!o.visible||o.material.opacity<.2)continue;for(const plane of planes){const cut=sectionGeometry(o,plane);if(!cut)continue;const m=sectionMaterial(o.material.userData.tissue,o.material.color);m.opacity=o.material.opacity;m.transparent=m.opacity<1;m.depthWrite=!m.transparent;m.clippingPlanes=planes.filter(p=>p!==plane);const cap=new THREE.Mesh(cut.geometry,m);cap.userData.source=o;const edge=new THREE.LineSegments(cut.outline,new THREE.LineBasicMaterial({color:o.material.userData.tissue==='bone'?'#eee0bb':'#503b36',transparent:true,opacity:.45,clippingPlanes:m.clippingPlanes}));edge.raycast=()=>{};this.group.add(cap,edge);}if(++i%12===0){this.render();await new Promise(r=>setTimeout(r,0));}}this.render();}
}
